FEAT.forEach(([f,g,k],i)=>add({id:'fe'+i,fam:'fe'+i,g,d:3,c:'Poomsae',q:`Welche Form zeichnet sich durch folgendes Merkmal aus: ${f}?`,a:k,w:shuffle(FEAT.filter(x=>x[2]!==k)).slice(0,4).map(x=>x[2]),x:`${k}: ${f}.`,fz:[k,k.replace('Taegeuk ','')],vs:FEAT.filter(x=>x[2]!==k).flatMap(x=>[x[2],x[2].replace('Taegeuk ','')])}));
